mapper.select:
SELECT cmpycd, meetingid, meetingtit, meetingdt, meetingtime, location, hostid, hostnm, content, summary, stt_text, audio_file_path, addtime, updtime, updemp FROM meeting_master_tbl WHERE cmpycd = #{cmpycd}
AND meetingid = #{meetingid}
AND meetingdt BETWEEN REPLACE(#{sdate}, '-', '') AND REPLACE(#{edate}, '-', '')
AND meetingtit LIKE CONCAT('%', #{meetingtit}, '%')
ORDER BY meetingdt DESC, meetingid DESC

SELECT cmpycd, meetingid, ser, userid, usernm, deptcd, deptnm, attendance_yn
  FROM meeting_attendee_tbl
 WHERE cmpycd = #{cmpycd}
   AND meetingid = #{meetingid}
 ORDER BY ser ASC

SELECT cmpycd, meetingid, fileid, filename, filepath, filesize, filetype, addtime
  FROM meeting_file_tbl
 WHERE cmpycd = #{cmpycd}
   AND meetingid = #{meetingid}
 ORDER BY fileid ASC

