SELECT CONCAT(#{meetingdt}, '-', LPAD(IFNULL(MAX(CAST(SUBSTRING_INDEX(meetingid, '-', -1) AS UNSIGNED)), 0) + 1, 3, '0'))
  FROM meeting_master_tbl
 WHERE cmpycd = #{cmpycd}
   AND meetingdt = #{meetingdt}
